1	import type * as core from "../core/index.js";
2	import type * as JSONSchema from "./json-schema.js";
3	import { type $ZodRegistry, globalRegistry } from "./registries.js";
4	import type * as schemas from "./schemas.js";
5	import type { StandardJSONSchemaV1, StandardSchemaWithJSONProps } from "./standard-schema.js";
6	import { assignProp } from "./util.js";
7	
8	function assignProps<T extends object>(target: T, ...sources: object[]): T {
9	  for (const source of sources) {
10	    for (const key of Reflect.ownKeys(source)) {
11	      if (Object.prototype.propertyIsEnumerable.call(source, key)) {
12	        assignProp(target, key, (source as any)[key]);
13	      }
14	    }
15	  }
16	  return target;
17	}
18	
19	export type Processor<T extends schemas.$ZodType = schemas.$ZodType> = (
20	  schema: T,
21	  ctx: ToJSONSchemaContext,
22	  json: JSONSchema.BaseSchema,
23	  params: ProcessParams
24	) => void;
25	
26	export interface JSONSchemaGeneratorParams {
27	  processors: Record<string, Processor>;
28	  /** A registry used to look up metadata for each schema. Any schema with an `id` property will be extracted as a $def.
29	   *  @default globalRegistry */
30	  metadata?: $ZodRegistry<Record<string, any>>;
31	  /** The JSON Schema version to target.
32	   * - `"draft-2020-12"` — Default. JSON Schema Draft 2020-12
33	   * - `"draft-07"` — JSON Schema Draft 7
34	   * - `"draft-04"` — JSON Schema Draft 4
35	   * - `"openapi-3.0"` — OpenAPI 3.0 Schema Object */
36	  target?: "draft-04" | "draft-07" | "draft-2020-12" | "openapi-3.0" | ({} & string) | undefined;
37	  /** How to handle unrepresentable types.
38	   * - `"throw"` — Default. Unrepresentable types throw an error
39	   * - `"any"` — Unrepresentable types become `{}` */
40	  unrepresentable?: "throw" | "any";
41	  /** Arbitrary custom logic that can be used to modify the generated JSON Schema. */
42	  override?: (ctx: {
43	    zodSchema: schemas.$ZodTypes;
44	    jsonSchema: JSONSchema.BaseSchema;
45	    path: (string | number)[];
46	  }) => void;
47	  /** Whether to extract the `"input"` or `"output"` type. Relevant to transforms, defaults, coerced primitives, etc.
48	   * - `"output"` — Default. Convert the output schema.
49	   * - `"input"` — Convert the input schema. */
50	  io?: "input" | "output";
51	  cycles?: "ref" | "throw";
52	  reused?: "ref" | "inline";
53	  external?:
54	    | {
55	        registry: $ZodRegistry<{ id?: string | undefined }>;
56	        uri?: ((id: string) => string) | undefined;
57	        defs: Record<string, JSONSchema.BaseSchema>;
58	      }
59	    | undefined;
60	}
61	
62	/**
63	 * Parameters for the toJSONSchema function.
64	 */
65	export type ToJSONSchemaParams = Omit<JSONSchemaGeneratorParams, "processors" | "external">;
66	
67	/**
68	 * Parameters for the toJSONSchema function when passing a registry.
69	 */
70	export interface RegistryToJSONSchemaParams extends ToJSONSchemaParams {
71	  uri?: (id: string) => string;
72	}
73	
74	export interface ProcessParams {
75	  schemaPath: schemas.$ZodType[];
76	  path: (string | number)[];
77	}
78	
79	export interface Seen {
80	  /** JSON Schema result for this Zod schema */
81	  schema: JSONSchema.BaseSchema;
82	  /** A cached version of the schema that doesn't get overwritten during ref resolution */
83	  def?: JSONSchema.BaseSchema;
84	  defId?: string | undefined;
85	  /** Number of times this schema was encountered during traversal */
86	  count: number;
87	  /** Cycle path */
88	  cycle?: (string | number)[] | undefined;
89	  isParent?: boolean | undefined;
90	  /** Schema to inherit JSON Schema properties from (set by processor for wrappers) */
91	  ref?: schemas.$ZodType | null;
92	  /** JSON Schema property path for this schema */
93	  path?: (string | number)[] | undefined;
94	}
95	
96	export interface ToJSONSchemaContext {
97	  processors: Record<string, Processor>;
98	  metadataRegistry: $ZodRegistry<Record<string, any>>;
99	  target: "draft-04" | "draft-07" | "draft-2020-12" | "openapi-3.0" | ({} & string);
100	  unrepresentable: "throw" | "any";
101	  override: (ctx: {
102	    // must be schemas.$ZodType to prevent recursive type resolution error
103	    zodSchema: schemas.$ZodType;
104	    jsonSchema: JSONSchema.BaseSchema;
105	    path: (string | number)[];
106	  }) => void;
107	  io: "input" | "output";
108	  counter: number;
109	  seen: Map<schemas.$ZodType, Seen>;
110	  cycles: "ref" | "throw";
111	  reused: "ref" | "inline";
112	  external?:
113	    | {
114	        registry: $ZodRegistry<{ id?: string | undefined }>;
115	        uri?: ((id: string) => string) | undefined;
116	        defs: Record<string, JSONSchema.BaseSchema>;
117	      }
118	    | undefined;
119	}
