130	export function initializeContext(params: JSONSchemaGeneratorParams): ToJSONSchemaContext {
131	  // Normalize target: convert old non-hyphenated versions to hyphenated versions
132	  let target: ToJSONSchemaContext["target"] = params?.target ?? "draft-2020-12";
133	  if (target === "draft-4") target = "draft-04";
134	  if (target === "draft-7") target = "draft-07";
135	
136	  return {
137	    processors: params.processors ?? {},
138	    metadataRegistry: params?.metadata ?? globalRegistry,
139	    target,
140	    unrepresentable: params?.unrepresentable ?? "throw",
141	    override: (params?.override as any) ?? (() => {}),
142	    io: params?.io ?? "output",
143	    counter: 0,
144	    seen: new Map(),
145	    cycles: params?.cycles ?? "ref",
146	    reused: params?.reused ?? "inline",
147	    external: params?.external ?? undefined,
148	  };
149	}
150	
151	export function process<T extends schemas.$ZodType>(
152	  schema: T,
153	  ctx: ToJSONSchemaContext,
154	  _params: ProcessParams = { path: [], schemaPath: [] }
155	): JSONSchema.BaseSchema {
156	  const def = schema._zod.def as schemas.$ZodTypes["_zod"]["def"];
157	
158	  // check for schema in seens
159	  const seen = ctx.seen.get(schema);
160	
161	  if (seen) {
162	    seen.count++;
163	
164	    // check if cycle
165	    const isCycle = _params.schemaPath.includes(schema);
166	    if (isCycle) {
167	      seen.cycle = _params.path;
168	    }
169	
170	    return seen.schema;
171	  }
172	
173	  // initialize
174	  const result: Seen = { schema: {}, count: 1, cycle: undefined, path: _params.path };
175	  ctx.seen.set(schema, result);
176	
177	  // custom method overrides default behavior
178	  const overrideSchema = schema._zod.toJSONSchema?.();
179	  if (overrideSchema) {
180	    result.schema = overrideSchema as any;
181	  } else {
182	    const params = {
183	      ..._params,
184	      schemaPath: [..._params.schemaPath, schema],
185	      path: _params.path,
186	    };
187	
188	    if (schema._zod.processJSONSchema) {
189	      schema._zod.processJSONSchema(ctx, result.schema, params);
190	    } else {
191	      const _json = result.schema;
192	      const processor = ctx.processors[def.type];
193	      if (!processor) {
194	        throw new Error(`[toJSONSchema]: Non-representable type encountered: ${def.type}`);
195	      }
196	      processor(schema, ctx, _json, params);
197	    }
198	
199	    const parent = schema._zod.parent as T;
200	
201	    if (parent) {
202	      // Also set ref if processor didn't (for inheritance)
203	      if (!result.ref) result.ref = parent;
204	      process(parent, ctx, params);
205	      ctx.seen.get(parent)!.isParent = true;
206	    }
207	  }
208	
209	  // metadata
210	  const meta = ctx.metadataRegistry.get(schema);
211	  if (meta) assignProps(result.schema, meta);
212	
213	  if (ctx.io === "input" && isTransforming(schema)) {
214	    // examples/defaults only apply to output type of pipe
215	    delete result.schema.examples;
216	    delete result.schema.default;
217	  }
218	
219	  // set prefault as default
220	  if (ctx.io === "input" && "_prefault" in result.schema) result.schema.default ??= result.schema._prefault;
221	  delete result.schema._prefault;
222	
223	  // pulling fresh from ctx.seen in case it was overwritten
224	  const _result = ctx.seen.get(schema)!;
225	
226	  return _result.schema;
227	}
