229	export function extractDefs<T extends schemas.$ZodType>(
230	  ctx: ToJSONSchemaContext,
231	  schema: T
232	  // params: EmitParams
233	): void {
234	  // iterate over seen map;
235	  const root = ctx.seen.get(schema);
236	
237	  if (!root) throw new Error("Unprocessed schema. This is a bug in Zod.");
238	
239	  // Track ids to detect duplicates across different schemas
240	  const idToSchema = new Map<string, schemas.$ZodType>();
241	  for (const entry of ctx.seen.entries()) {
242	    const id = ctx.metadataRegistry.get(entry[0])?.id;
243	    if (id) {
244	      const existing = idToSchema.get(id);
245	      if (existing && existing !== entry[0]) {
246	        throw new Error(
247	          `Duplicate schema id "${id}" detected during JSON Schema conversion. Two different schemas cannot share the same id when converted together.`
248	        );
249	      }
250	      idToSchema.set(id, entry[0]);
251	    }
252	  }
253	
254	  // returns a ref to the schema
255	  // defId will be empty if the ref points to an external schema (or #)
256	  const makeURI = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): { ref: string; defId?: string } => {
257	    // comparing the seen objects because sometimes
258	    // multiple schemas map to the same seen object.
259	    // e.g. lazy
260	
261	    // external is configured
262	    const defsSegment = ctx.target === "draft-2020-12" ? "$defs" : "definitions";
263	    if (ctx.external) {
264	      const externalId = ctx.external.registry.get(entry[0])?.id; // ?? "__shared";// `__schema${ctx.counter++}`;
265	
266	      // check if schema is in the external registry
267	      const uriGenerator = ctx.external.uri ?? ((id: string) => id);
268	      if (externalId) {
269	        return { ref: uriGenerator(externalId) };
270	      }
271	
272	      // otherwise, add to __shared
273	      const id: string = entry[1].defId ?? (entry[1].schema.id as string) ?? `schema${ctx.counter++}`;
274	      entry[1].defId = id; // set defId so it will be reused if needed
275	      return { defId: id, ref: `${uriGenerator("__shared")}#/${defsSegment}/${id}` };
276	    }
277	
278	    if (entry[1] === root) {
279	      return { ref: "#" };
280	    }
281	
282	    // self-contained schema
283	    const uriPrefix = `#`;
284	    const defUriPrefix = `${uriPrefix}/${defsSegment}/`;
285	    const defId = entry[1].schema.id ?? `__schema${ctx.counter++}`;
286	    return { defId, ref: defUriPrefix + defId };
287	  };
288	
289	  // stored cached version in `def` property
290	  // remove all properties, set $ref
291	  const extractToDef = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): void => {
292	    // if the schema is already a reference, do not extract it
293	    if (entry[1].schema.$ref) {
294	      return;
295	    }
296	    const seen = entry[1];
297	    const { ref, defId } = makeURI(entry);
298	
299	    seen.def = { ...seen.schema };
300	    // defId won't be set if the schema is a reference to an external schema
301	    // or if the schema is the root schema
302	    if (defId) seen.defId = defId;
303	    // wipe away all properties except $ref
304	    const schema = seen.schema;
305	    for (const key in schema) {
306	      delete schema[key];
307	    }
308	    schema.$ref = ref;
309	  };
310	
311	  // throw on cycles
312	
313	  // break cycles
314	  if (ctx.cycles === "throw") {
315	    for (const entry of ctx.seen.entries()) {
316	      const seen = entry[1];
317	      if (seen.cycle) {
318	        throw new Error(
319	          "Cycle detected: " +
320	            `#/${seen.cycle?.join("/")}/<root>` +
321	            '\n\nSet the `cycles` parameter to `"ref"` to resolve cyclical schemas with defs.'
322	        );
323	      }
324	    }
325	  }
326	
327	  // extract schemas into $defs
328	  for (const entry of ctx.seen.entries()) {
329	    const seen = entry[1];
330	
331	    // convert root schema to # $ref
332	    if (schema === entry[0]) {
333	      extractToDef(entry); // this has special handling for the root schema
334	      continue;
335	    }
336	
337	    // extract schemas that are in the external registry
338	    if (ctx.external) {
339	      const ext = ctx.external.registry.get(entry[0])?.id;
340	      if (schema !== entry[0] && ext) {
341	        extractToDef(entry);
342	        continue;
343	      }
344	    }
345	
346	    // extract schemas with `id` meta
347	    const id = ctx.metadataRegistry.get(entry[0])?.id;
348	    if (id) {
349	      extractToDef(entry);
350	      continue;
351	    }
352	
353	    // break cycles
354	    if (seen.cycle) {
355	      // any
356	      extractToDef(entry);
357	      continue;
358	    }
359	
360	    // extract reused schemas
361	    if (seen.count > 1) {
362	      if (ctx.reused === "ref") {
363	        extractToDef(entry);
364	        // biome-ignore lint:
365	        continue;
366	      }
367	    }
368	  }
369	}
370	
371	export function finalize<T extends schemas.$ZodType>(
372	  ctx: ToJSONSchemaContext,
373	  schema: T
374	): ZodStandardJSONSchemaPayload<T> {
375	  const root = ctx.seen.get(schema);
376	  if (!root) throw new Error("Unprocessed schema. This is a bug in Zod.");
377	
378	  // flatten refs - inherit properties from parent schemas
379	  const flattenRef = (zodSchema: schemas.$ZodType) => {
380	    const seen = ctx.seen.get(zodSchema)!;
381	
382	    // already processed
383	    if (seen.ref === null) return;
384	
385	    const schema = seen.def ?? seen.schema;
386	    const _cached = { ...schema };
387	
388	    const ref = seen.ref;
389	    seen.ref = null; // prevent infinite recursion
390	
391	    if (ref) {
392	      flattenRef(ref);
393	
394	      const refSeen = ctx.seen.get(ref)!;
395	      const refSchema = refSeen.schema;
396	
397	      // merge referenced schema into current
398	      if (refSchema.$ref && (ctx.target === "draft-07" || ctx.target === "draft-04" || ctx.target === "openapi-3.0")) {
399	        // older drafts can't combine $ref with other properties
400	        schema.allOf = schema.allOf ?? [];
401	        schema.allOf.push(refSchema);
402	      } else {
403	        assignProps(schema, refSchema);
404	      }
405	      // restore child's own properties (child wins)
406	      assignProps(schema, _cached);
407	
408	      const isParentRef = zodSchema._zod.parent === ref;
409	
410	      // For parent chain, child is a refinement - remove parent-only properties
411	      if (isParentRef) {
412	        for (const key in schema) {
413	          if (key === "$ref" || key === "allOf") continue;
414	          if (!(key in _cached)) {
415	            delete schema[key];
416	          }
417	        }
418	      }
419	
420	      // When ref was extracted to $defs, remove properties that match the definition
421	      if (refSchema.$ref && refSeen.def) {
422	        for (const key in schema) {
423	          if (key === "$ref" || key === "allOf") continue;
424	          if (key in refSeen.def && JSON.stringify(schema[key]) === JSON.stringify(refSeen.def[key])) {
425	            delete schema[key];
426	          }
427	        }
428	      }
429	    }
430	
431	    // If parent was extracted (has $ref), propagate $ref to this schema
432	    // This handles cases like: readonly().meta({id}).describe()
433	    // where processor sets ref to innerType but parent should be referenced
434	    const parent = zodSchema._zod.parent;
435	    if (parent && parent !== ref) {
436	      // Ensure parent is processed first so its def has inherited properties
437	      flattenRef(parent);
438	      const parentSeen = ctx.seen.get(parent);
439	      if (parentSeen?.schema.$ref) {
440	        schema.$ref = parentSeen.schema.$ref;
441	        // De-duplicate with parent's definition
442	        if (parentSeen.def) {
443	          for (const key in schema) {
444	            if (key === "$ref" || key === "allOf") continue;
445	            if (key in parentSeen.def && JSON.stringify(schema[key]) === JSON.stringify(parentSeen.def[key])) {
446	              delete schema[key];
447	            }
448	          }
449	        }
450	      }
451	    }
452	
453	    // execute overrides
454	    ctx.override({
455	      zodSchema: zodSchema as schemas.$ZodTypes,
456	      jsonSchema: schema,
457	      path: seen.path ?? [],
458	    });
459	  };
460	
461	  for (const entry of [...ctx.seen.entries()].reverse()) {
462	    flattenRef(entry[0]);
463	  }
464	
465	  const result: JSONSchema.BaseSchema = {};
466	  if (ctx.target === "draft-2020-12") {
467	    result.$schema = "https://json-schema.org/draft/2020-12/schema";
468	  } else if (ctx.target === "draft-07") {
469	    result.$schema = "http://json-schema.org/draft-07/schema#";
470	  } else if (ctx.target === "draft-04") {
471	    result.$schema = "http://json-schema.org/draft-04/schema#";
472	  } else if (ctx.target === "openapi-3.0") {
473	    // OpenAPI 3.0 schema objects should not include a $schema property
474	  } else {
475	    // Arbitrary string values are allowed but won't have a $schema property set
476	  }
477	
478	  if (ctx.external?.uri) {
479	    const id = ctx.external.registry.get(schema)?.id;
480	    if (!id) throw new Error("Schema is missing an `id` property");
481	    result.$id = ctx.external.uri(id);
482	  }
483	
484	  assignProps(result, root.def ?? root.schema);
485	
486	  // The `id` in `.meta()` is a Zod-specific registration tag used to extract
487	  // schemas into $defs — it is not user-facing JSON Schema metadata. Strip it
488	  // from the output body where it would otherwise leak. The id is preserved
489	  // implicitly via the $defs key (and via $ref paths).
490	  const rootMetaId = ctx.metadataRegistry.get(schema)?.id;
491	  if (rootMetaId !== undefined && result.id === rootMetaId) delete result.id;
492	
493	  // build defs object
494	  const defs: JSONSchema.BaseSchema["$defs"] = ctx.external?.defs ?? {};
495	  for (const entry of ctx.seen.entries()) {
496	    const seen = entry[1];
497	    if (seen.def && seen.defId) {
498	      if (seen.def.id === seen.defId) delete seen.def.id;
499	      assignProp(defs, seen.defId, seen.def);
500	    }
501	  }
502	
503	  // set definitions in result
504	  if (ctx.external) {
505	  } else {
506	    if (Object.keys(defs).length > 0) {
507	      if (ctx.target === "draft-2020-12") {
508	        result.$defs = defs;
509	      } else {
510	        result.definitions = defs;
511	      }
512	    }
513	  }
514	
515	  try {
516	    // this "finalizes" this schema and ensures all cycles are removed
517	    // each call to finalize() is functionally independent
518	    // though the seen map is shared
519	    const finalized = JSON.parse(JSON.stringify(result));
520	    Object.defineProperty(finalized, "~standard", {
521	      value: {
522	        ...schema["~standard"],
523	        jsonSchema: {
524	          input: createStandardJSONSchemaMethod(schema, "input", ctx.processors),
525	          output: createStandardJSONSchemaMethod(schema, "output", ctx.processors),
526	        },
527	      },
528	      enumerable: false,
529	      writable: false,
530	    });
531	
532	    return finalized;
533	  } catch (_err) {
534	    throw new Error("Error converting schema to JSON.");
535	  }
536	}
