538	function isTransforming(
539	  _schema: schemas.$ZodType,
540	  _ctx?: {
541	    seen: Set<schemas.$ZodType>;
542	  }
543	): boolean {
544	  const ctx = _ctx ?? { seen: new Set() };
545	
546	  if (ctx.seen.has(_schema)) return false;
547	  ctx.seen.add(_schema);
548	
549	  const def = (_schema as schemas.$ZodTypes)._zod.def;
550	
551	  if (def.type === "transform") return true;
552	
553	  if (def.type === "array") return isTransforming(def.element, ctx);
554	  if (def.type === "set") return isTransforming(def.valueType, ctx);
555	  if (def.type === "lazy") return isTransforming(def.getter(), ctx);
556	
557	  if (
558	    def.type === "promise" ||
559	    def.type === "optional" ||
560	    def.type === "nonoptional" ||
561	    def.type === "nullable" ||
562	    def.type === "readonly" ||
563	    def.type === "default" ||
564	    def.type === "prefault"
565	  ) {
566	    return isTransforming(def.innerType, ctx);
567	  }
568	
569	  if (def.type === "intersection") {
570	    return isTransforming(def.left, ctx) || isTransforming(def.right, ctx);
571	  }
572	  if (def.type === "record" || def.type === "map") {
573	    return isTransforming(def.keyType, ctx) || isTransforming(def.valueType, ctx);
574	  }
575	  if (def.type === "pipe") {
576	    if (_schema._zod.traits.has("$ZodCodec")) return true;
577	    return isTransforming(def.in, ctx) || isTransforming(def.out, ctx);
578	  }
579	
580	  if (def.type === "object") {
581	    for (const key in def.shape) {
582	      if (isTransforming(def.shape[key]!, ctx)) return true;
583	    }
584	    return false;
585	  }
586	  if (def.type === "union") {
587	    for (const option of def.options) {
588	      if (isTransforming(option, ctx)) return true;
589	    }
590	    return false;
591	  }
592	  if (def.type === "tuple") {
593	    for (const item of def.items) {
594	      if (isTransforming(item, ctx)) return true;
595	    }
596	    if (def.rest && isTransforming(def.rest, ctx)) return true;
597	    return false;
598	  }
599	
600	  return false;
601	}
