603	export type ZodStandardSchemaWithJSON<T> = StandardSchemaWithJSONProps<core.input<T>, core.output<T>>;
604	export interface ZodStandardJSONSchemaPayload<T> extends JSONSchema.BaseSchema {
605	  "~standard": ZodStandardSchemaWithJSON<T>;
606	}
607	
608	/**
609	 * Creates a toJSONSchema method for a schema instance.
610	 * This encapsulates the logic of initializing context, processing, extracting defs, and finalizing.
611	 */
612	export const createToJSONSchemaMethod =
613	  <T extends schemas.$ZodType>(schema: T, processors: Record<string, Processor> = {}) =>
614	  (params?: ToJSONSchemaParams): ZodStandardJSONSchemaPayload<T> => {
615	    const ctx = initializeContext({ ...params, processors });
616	    process(schema, ctx);
617	    extractDefs(ctx, schema);
618	    return finalize(ctx, schema);
619	  };
620	
621	/**
622	 * Creates a toJSONSchema method for a schema instance.
623	 * This encapsulates the logic of initializing context, processing, extracting defs, and finalizing.
624	 */
625	type StandardJSONSchemaMethodParams = Parameters<StandardJSONSchemaV1["~standard"]["jsonSchema"]["input"]>[0];
626	export const createStandardJSONSchemaMethod =
627	  <T extends schemas.$ZodType>(schema: T, io: "input" | "output", processors: Record<string, Processor> = {}) =>
