27	export const stringProcessor: Processor<schemas.$ZodString> = (schema, ctx, _json, _params) => {
28	  const json = _json as JSONSchema.StringSchema;
29	  json.type = "string";
30	  const { minimum, maximum, format, patterns, contentEncoding } = schema._zod
31	    .bag as schemas.$ZodStringInternals<unknown>["bag"];
32	  if (typeof minimum === "number") json.minLength = minimum;
33	  if (typeof maximum === "number") json.maxLength = maximum;
34	  // custom pattern overrides format
35	  if (format) {
36	    json.format = formatMap[format as checks.$ZodStringFormats] ?? format;
37	    if (json.format === "") delete json.format; // empty format is not valid
38	
39	    // JSON Schema format: "time" requires a full time with offset or Z
40	    // z.iso.time() does not include timezone information, so format: "time" should never be used
41	    if (format === "time") {
42	      delete json.format;
43	    }
44	  }
45	  if (contentEncoding) json.contentEncoding = contentEncoding;
46	  if (patterns && patterns.size > 0) {
47	    const regexes = [...patterns];
48	    if (regexes.length === 1) json.pattern = regexes[0]!.source;
49	    else if (regexes.length > 1) {
50	      json.allOf = [
51	        ...regexes.map((regex) => ({
52	          ...(ctx.target === "draft-07" || ctx.target === "draft-04" || ctx.target === "openapi-3.0"
53	            ? ({ type: "string" } as const)
54	            : {}),
55	          pattern: regex.source,
56	        })),
57	      ];
58	    }
59	  }
60	};
61	
62	export const numberProcessor: Processor<schemas.$ZodNumber> = (schema, ctx, _json, _params) => {
63	  const json = _json as JSONSchema.NumberSchema | JSONSchema.IntegerSchema;
64	  const { minimum, maximum, format, multipleOf, exclusiveMaximum, exclusiveMinimum } = schema._zod.bag;
65	  if (typeof format === "string" && format.includes("int")) json.type = "integer";
66	  else json.type = "number";
67	
68	  // when both minimum and exclusiveMinimum exist, pick the more restrictive one
69	  const exMin = typeof exclusiveMinimum === "number" && exclusiveMinimum >= (minimum ?? Number.NEGATIVE_INFINITY);
70	  const exMax = typeof exclusiveMaximum === "number" && exclusiveMaximum <= (maximum ?? Number.POSITIVE_INFINITY);
71	  const legacy = ctx.target === "draft-04" || ctx.target === "openapi-3.0";
