  for (const val of def.values) {
    if (val === undefined) {
      flagUnrepresentable(schema, ctx, "Literal `undefined` cannot be represented in JSON Schema"); else 
    } else if (typeof val === "bigint") {
      flagUnrepresentable(schema, ctx, "BigInt literals cannot be represented in JSON Schema"); else 
        vals.push(Number(val));
    } else {
      vals.push(val);
    }
  }
  if (vals.length === 0) {
    // do nothing (an undefined literal was stripped)
  } else if (vals.length === 1) {
    const val = vals[0]!;
    json.type = val === null ? ("null" as const) : (typeof val as any);
    if (ctx.target === "draft-04" || ctx.target === "openapi-3.0") {
      json.enum = [val];
    } else {
      json.const = val;
    }
  } else {
    if (vals.every((v) => typeof v === "number")) json.type = "number";
    if (vals.every((v) => typeof v === "string")) json.type = "string";
    if (vals.every((v) => typeof v === "boolean")) json.type = "boolean";
    if (vals.every((v) => v === null)) json.type = "null";
